# ---- Предложение: знаки в конце, виды
SE = [('Как тебя зовут', '?'), ('Какая сегодня погода', '?'), ('Ты любишь читать', '?'), ('Где находится библиотека', '?'), ('Мама читает книгу', '.'), ('Весной цветут сады', '.'), ('Мы идём в школу', '.'),
      ('Ура, мы победили', '!'), ('Как красиво вокруг', '!'), ('Какой чудесный день', '!'), ('Сколько тебе лет', '?'), ('Зимой выпал снег', '.'), ('Помогите мне', '!'), ('Закройте дверь', '.')]
SE = [x for x in SE if x[0] not in ('Закройте дверь', 'Помогите мне')]
def se1():
    s, p = ch(SE); return mc(f'Какой знак нужен в конце предложения: «{s}…»', {'.': 'точка', '?': 'вопросительный знак', '!': 'восклицательный знак'}[p], [x for x in ['точка', 'вопросительный знак', 'восклицательный знак', 'запятая'] if x != {'.': 'точка', '?': 'вопросительный знак', '!': 'восклицательный знак'}[p]])
def se2():
    t = {'точка': ('повествовательное', [x for x, p in SE if p == '.']), 'вопросительный знак': ('вопросительное', [x for x, p in SE if p == '?']), 'восклицательный знак': ('восклицательное', [x for x, p in SE if p == '!'])}
    k = ch(list(t)); name, ws = t[k]; s = ch(ws); return mc(f'Какое это предложение по цели высказывания и интонации: «{s}»?', name, [x for x in ['повествовательное', 'вопросительное', 'восклицательное', 'побудительное'] if x != name])
def se3():
    return ch([mc('Предложение — это...', 'Слово или несколько слов, выражающие законченную мысль', ['Два слова, связанные по смыслу', 'Часть слова', 'Группа звуков']), mc('Какое предложение вопросительное?', 'Как тебя зовут?', ['Меня зовут Али.', 'Как красиво!', 'Закрой окно.']),
               mc('В конце повествовательного предложения ставится:', 'точка', ['запятая', 'двоеточие', 'тире']), mc('Какое предложение восклицательное?', 'Какой чудесный день!', ['Какой сегодня день?', 'Сегодня хороший день.', 'Какой день сегодня']) ])
B.topic(BX, 'r_predl', 'Предложение — Gap', [5, 6, 7, 8], se1, se2, lambda: ch([se2, se3])(), 'предложение gap знаки препинания')

