# ---- Однородные, обращение, вводные, прямая речь
OD = ['В саду растут яблони, груши и вишни.', 'Я люблю чай, кофе и сок.', 'Дети читают, пишут и рисуют.', 'Мы купили хлеб, молоко и сыр.', 'Осенью листья жёлтые, красные и оранжевые.']
def od1():
    return ch([mc('Где запятые расставлены правильно?', 'Я купил хлеб, молоко и сыр.', ['Я купил хлеб молоко и сыр.', 'Я купил, хлеб, молоко, и сыр.', 'Я купил хлеб, молоко, и, сыр.']),
               mc('Где запятые расставлены правильно?', 'Не чай, а кофе.', ['Не чай а кофе.', 'Не, чай, а кофе.', 'Не чай а, кофе.']), mc('Нужна ли запятая: Я люблю чай и кофе?', 'Не нужна', ['Нужна перед «и»', 'Нужна после «люблю»', 'Нужна после «чай»']),
               mc('Какие слова являются однородными членами: «Дети читают, пишут и рисуют»?', 'читают, пишут, рисуют', ['дети, читают', 'пишут, дети', 'читают, дети, и']), mc('Как называются члены предложения, отвечающие на один вопрос и относящиеся к одному слову?', 'однородные', ['главные', 'сложные', 'вводные']),
               mc('Какой союз соединяет однородные члены противопоставлением?', 'но, а', ['и, да', 'или, либо', 'что, чтобы'])])
FRS = [('В саду растут {}.', ['яблони', 'груши', 'вишни', 'сливы']), ('Я купил {}.', ['хлеб', 'молоко', 'сыр', 'масло']), ('На столе лежат {}.', ['книги', 'тетради', 'ручки', 'карандаши']),
       ('Мы любим {}.', ['лето', 'весну', 'осень', 'зиму']), ('В классе сидят {}.', ['Али', 'Лола', 'Анвар', 'Зарина']), ('В корзине лежали {}.', ['яблоки', 'груши', 'виноград', 'абрикосы']),
       ('Дети рисуют {}.', ['дом', 'дерево', 'солнце', 'цветы'])]
def od2():
    f, ws = ch(FRS); a, b, c = R.sample(ws, 3); good = f.format(f'{a}, {b} и {c}')
    return mc('Где запятые расставлены правильно?', good, [f.format(f'{a} {b} и {c}'), f.format(f'{a}, {b}, и {c}'), f.format(f'{a}, {b} и, {c}')])
def od3():
    f, ws = ch(FRS); a, b = R.sample(ws, 2); return mc('Нужна ли запятая в предложении?  ' + f.format(f'{a} и {b}'), 'Не нужна', ['Нужна перед «и»', 'Нужна после «и»', 'Нужны две запятые'])
B.topic(BX, 'r_odnorod', 'Однородные члены предложения', [7, 8], lambda: ch([od2, od3, od1])(), lambda: ch([od2, od1])(), lambda: ch([od2, od2, od1])(), 'однородные члены bir jinsli boʻlaklar')

OB = [('Мама, посмотри на меня!', 'мама'), ('Ребята, откройте тетради.', 'ребята'), ('Здравствуй, Али!', 'али'), ('Друг, помоги мне.', 'друг'), ('Дорогая бабушка, спасибо за подарок!', 'бабушка'), ('Дети, идите к столу.', 'дети'),
      ('Лола, где твой портфель?', 'лола'), ('Учитель, можно войти?', 'учитель')]
def ob1():
    s, w = ch(OB); ws = [x.strip('.,!?').lower() for x in s.split()]; p = [x for x in ws if x != w]
    ex = [x.strip('.,!?').lower() for t, _ in OB if t != s for x in t.split()]; ex = [x for x in ex if x not in ws and x != w]
    p += R.sample(ex, max(0, 3 - len(p))); return mc(f'Найдите обращение: {s}', w, R.sample(p, 3))
def ob2():
    return ch([mc('Где правильно расставлены знаки?', 'Мама, посмотри на меня!', ['Мама посмотри на меня!', 'Мама посмотри, на меня!', 'Мама; посмотри на меня!']), mc('Где правильно расставлены знаки?', 'Ребята, откройте тетради.', ['Ребята откройте тетради.', 'Ребята: откройте тетради.', 'Ребята-откройте тетради.']),
               mc('Что такое обращение?', 'Слово, называющее того, к кому обращена речь', ['Слово, называющее действие', 'Главный член предложения', 'Часть слова']), mc('Как выделяется обращение на письме?', 'Запятыми (или восклицательным знаком)', ['Кавычками', 'Скобками', 'Не выделяется'])])
B.topic(BX, 'r_obrash', 'Обращение — Murojaat', [7, 8], lambda: ch([ob1, ob1, ob2])(), ob2 if False else (lambda: ch([ob1, ob2])()), lambda: ch([ob1, ob2])(), 'обращение murojaat запятая')

VV = [('Завтра, наверное, будет дождь.', 'наверное'), ('Он, конечно, придёт.', 'конечно'), ('К сожалению, я не смог прийти.', 'сожалению'), ('Мы, например, ходили в музей.', 'например'), ('Погода, по-моему, улучшится.', 'по-моему'),
      ('Вероятно, он опоздает на урок.', 'вероятно'), ('К счастью, все остались живы.', 'счастью'), ('Он, кстати, тоже придёт.', 'кстати')]
def vv1():
    s, w = ch(VV); ws = [x.strip('.,!?') for x in s.split()]; p = [x for x in ws if x != w]
    ex = [x.strip('.,!?') for t, _ in VV if t != s for x in t.split()]; ex = [x for x in ex if x not in ws and x != w]
